<template><div class="form-view"><div class="form-heading"><span class="form-kicker">OPEN INVITATION</span><h2>创建你的账号</h2><p>邀请码用于守护 Creator SN 社区的质量。</p></div><form @submit.prevent="submit"><label>账号<input v-model.trim="form.userid" autocomplete="username" placeholder="邮箱、字母或数字" /></label><label>密码<input v-model="form.pwd" type="password" autocomplete="new-password" placeholder="至少 6 位密码" /></label><label>确认密码<input v-model="confirm" type="password" autocomplete="new-password" /></label><label>邀请码<input v-model.trim="form.invite_code" placeholder="请输入邀请码" /></label><p v-if="error" class="error">{{ error }}</p><p v-if="success" class="success">注册成功，正在返回登录页…</p><button class="primary-button" :disabled="loading">{{ loading ? "创建中…" : "注册账号" }}</button></form><div class="form-foot"><span>已有账号？</span><router-link to="/login">返回登录</router-link></div></div></template>
<script setup>
import { reactive,ref } from "vue";import { useRouter } from "vue-router";import { UserApi } from "@/api";
const router=useRouter(),form=reactive({userid:"",pwd:"",invite_code:""}),confirm=ref(""),loading=ref(false),error=ref(""),success=ref(false);
async function submit(){error.value="";if(!form.userid||!form.pwd||!form.invite_code){error.value="请完整填写注册信息";return}if(form.pwd.length<6){error.value="密码至少需要 6 位";return}if(form.pwd!==confirm.value){error.value="两次密码不一致";return}loading.value=true;try{const result=await UserApi.register(form);if(result.code!==200)throw new Error(result.message||"注册失败");success.value=true;setTimeout(()=>router.push("/login"),700)}catch(e){error.value=e.message||"注册失败"}finally{loading.value=false}}
</script>
<style scoped lang="scss">.form-view{display:grid;gap:24px}.form-heading h2{margin:8px 0;font-size:28px}.form-heading p{margin:0;color:#817b93}.form-kicker{font-size:11px;color:#b25fba;letter-spacing:.16em;font-weight:800}form{display:grid;gap:14px}label{display:grid;gap:7px;font-size:13px;color:#504867;font-weight:700}input{width:100%;padding:12px 14px;border:1px solid #e1d8ee;border-radius:12px;background:rgba(255,255,255,.8);font:inherit;outline:none}.primary-button{padding:14px;border:0;border-radius:12px;background:linear-gradient(120deg,#9c69d7,#e27bc7);color:#fff;font-weight:800;font-size:15px;cursor:pointer}.error{color:#ba4e70;font-size:13px}.success{color:#438d72;font-size:13px}.form-foot{font-size:13px;color:#817b93}.form-foot a{margin-left:6px;color:#8759b6;font-weight:700;text-decoration:none}</style>
